float min_distance = std::numeric_limits<float>::max();
RouteModel::Node* closest_node = nullptr;

for (auto& node : graph.SNodes()) {
    bool is_footway = false;
    auto it = graph.get_node_to_roadmap().find(node.index_);
    if (it != graph.get_node_to_roadmap().end()) {
        for (const auto* road : it->second) {
            if (road->type == Model::Road::Type::Footway) {
                is_footway = true;
                break;
            }
        }
    }
    if (is_footway) continue;

    float dx = node.x - x;
    float dy = node.y - y;
    float distance = std::sqrt(dx * dx + dy * dy);

    if (distance < min_distance) {
        min_distance = distance;
        closest_node = &node;
    }
}

return closest_node;

